import { MakeLogicType, afterMount, kea, path } from 'kea'
import { loaders } from 'kea-loaders'

import { getCurrentTeamId } from 'lib/utils/getAppContext'

import { secureConnectionsCreate, secureConnectionsRetrieve, secureConnectionsTestRetrieve } from './generated/api'
import type {
    SecureConnectionEnrollmentApi,
    SecureConnectionStatusApi,
    SecureConnectionTestApi,
} from './generated/api.schemas'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface secureConnectionsLogicValues {
    connectionStatus: SecureConnectionStatusApi | null
    connectionStatusLoading: boolean
    enrollment: SecureConnectionEnrollmentApi | null
    enrollmentLoading: boolean
    testResult: SecureConnectionTestApi | null
    testResultLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface secureConnectionsLogicActions {
    createEnrollment: () => any
    createEnrollmentFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    createEnrollmentSuccess: (
        enrollment: SecureConnectionEnrollmentApi,
        payload?: any
    ) => {
        enrollment: SecureConnectionEnrollmentApi
        payload?: any
    }
    loadConnectionStatus: () => any
    loadConnectionStatusFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadConnectionStatusSuccess: (
        connectionStatus: SecureConnectionStatusApi,
        payload?: any
    ) => {
        connectionStatus: SecureConnectionStatusApi
        payload?: any
    }
    testConnection: () => any
    testConnectionFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    testConnectionSuccess: (
        testResult: SecureConnectionTestApi,
        payload?: any
    ) => {
        testResult: SecureConnectionTestApi
        payload?: any
    }
}

export type secureConnectionsLogicType = MakeLogicType<secureConnectionsLogicValues, secureConnectionsLogicActions>

export const secureConnectionsLogic = kea<secureConnectionsLogicType>([
    path(['products', 'secureConnections', 'secureConnectionsLogic']),
    loaders(() => ({
        connectionStatus: [
            null as SecureConnectionStatusApi | null,
            {
                loadConnectionStatus: async () => secureConnectionsRetrieve(String(getCurrentTeamId())),
            },
        ],
        enrollment: [
            null as SecureConnectionEnrollmentApi | null,
            {
                createEnrollment: async () => secureConnectionsCreate(String(getCurrentTeamId())),
            },
        ],
        testResult: [
            null as SecureConnectionTestApi | null,
            {
                testConnection: async () => secureConnectionsTestRetrieve(String(getCurrentTeamId())),
            },
        ],
    })),
    afterMount(({ actions }) => {
        actions.loadConnectionStatus()
    }),
])
